return-response.set-body:
@{
                        var allowed = "{{llm-allowed-models}}";
                        var items = new JArray();

                        foreach (var name in allowed.Split(',')) {
                            if (name.Trim().Length == 0) { continue; }

                            items.Add(new JObject(
                                new JProperty("id", name.Trim()),
                                new JProperty("object", "model"),
                                new JProperty("owned_by", "azure-apim")
                            ));
                        }

                        return new JObject(
                            new JProperty("object", "list"),
                            new JProperty("data", items)
                        ).ToString();
                    }

set-variable.value:
@{
            var body = context.Request.Body?.As<JObject>(preserveContent: true);

            if (body == null || body["model"] == null) {
                return "";
            }
            return (string)body["model"];
        }

@{
            var model = (string)context.Variables["requestModel"];
            var allowed = "{{llm-allowed-models}}";

            foreach (var name in allowed.Split(',')) {
                if (name.Trim() == model) {
                    return true;
                }
            }
            return false;
        }

return-response.set-body:
@{
                        var model = (string)context.Variables["requestModel"];
                        var message = "Model '" + model + "' is not in the approved allowlist.";

                        return new JObject(
                            new JProperty("error", new JObject(
                                new JProperty("code", "model_not_approved"),
                                new JProperty("message", message)
                            ))
                        ).ToString();
                    }

set-variable.value:
@{
            var model = (string)context.Variables["requestModel"];
            var priceTable = "{{llm-price-table}}";
            string matched = null;
            string fallback = null;

            foreach (var row in priceTable.Split(',')) {
                var columns = row.Split(':');
                if (columns.Length != 3) { continue; }

                if (columns[0].Trim() == model) {
                    matched = columns[1].Trim();
                }
                if (columns[0].Trim() == "__default__") {
                    fallback = columns[1].Trim();
                }
            }
            return matched ?? fallback ?? "0";
        }

@{
            var model = (string)context.Variables["requestModel"];
            var priceTable = "{{llm-price-table}}";
            string matched = null;
            string fallback = null;

            foreach (var row in priceTable.Split(',')) {
                var columns = row.Split(':');
                if (columns.Length != 3) { continue; }

                if (columns[0].Trim() == model) {
                    matched = columns[2].Trim();
                }
                if (columns[0].Trim() == "__default__") {
                    fallback = columns[2].Trim();
                }
            }
            return matched ?? fallback ?? "0";
        }

@{
            var raw = context.Request.Headers.GetValueOrDefault("X-User-Id", "");

            if (string.IsNullOrWhiteSpace(raw)) {
                return "unassigned";
            }

            var trimmed = raw.Trim();
            return trimmed.Length <= 64 ? trimmed : trimmed.Substring(0, 64);
        }
